// BLP2 decoder of the browser-side client-file reader: a port of tools/ArcaneCore.Atlas/Textures (BlpFile, BlpDecoder, DxtCodec)
// that decodes a BLP2 file (type 1: palettized with 0, 1, 4 or 8 bit alpha, DXT1, DXT3, DXT5, raw BGRA) to straight-alpha RGBA8
// with the whole mip chain, level 0 first, down to 1x1. Levels the file does not hold are generated by the same alpha-weighted
// 2x2 box filter as BlpDecoder.BoxDown, so the output is meant to equal the C# decoder's (checked on synthetic files, not byte-compared with it).
//
// A level is valid only when it lies inside the file, starts after the header (and palette) and has exactly the size its encoding
// implies; the first invalid level ends the chain (when `hasMips` is 0 only level 0 counts). Every failure is a ClientFsError
// 'bad-file' with the reason; no image-sized allocation happens before the file proves it holds level 0.
// Thread affinity: pure functions, any thread (the reader calls them in its Workers).

import { badFile } from './limits.js';

export const HEADER_BYTES = 148;
export const PALETTE_BYTES = 1024;
export const MAX_DIMENSION = 4096;
export const MAX_LISTED_LEVELS = 16;
/** Largest decoded size (all levels, RGBA8) a file may have (BlpFile.MaxDecodedBytes). */
export const MAX_DECODED_BYTES = 64 * 1024 * 1024;

const COMPRESSION = Object.freeze({ PALETTIZED: 1, DXT: 2, RAW: 3 });

const levelSize = (width, height, level) => [Math.max(1, width >> level), Math.max(1, height >> level)];

const dxtLevelBytes = (width, height, blockBytes) => Math.ceil(Math.max(1, width) / 4) * Math.ceil(Math.max(1, height) / 4) * blockBytes;

/** The validated header and level table of a BLP2 file (BlpFile.Parse). */
export function parseBlpHeader(file) {
    if (!(file instanceof Uint8Array)) {
        throw badFile('BLP: the data is not a byte array.');
    }
    if (file.length < HEADER_BYTES) {
        throw badFile(`BLP is ${file.length} bytes, shorter than its ${HEADER_BYTES}-byte header.`);
    }
    if (file[0] !== 0x42 || file[1] !== 0x4C || file[2] !== 0x50 || file[3] !== 0x32) {
        throw badFile('Not a BLP2 file (bad magic).');
    }
    const view = new DataView(file.buffer, file.byteOffset, file.byteLength);
    const type = view.getUint32(4, true);
    if (type === 0) {
        throw badFile('jpeg BLP not supported.');
    }
    if (type !== 1) {
        throw badFile(`Unknown BLP2 type ${type}.`);
    }
    const width = view.getUint32(12, true);
    const height = view.getUint32(16, true);
    if (width < 1 || width > MAX_DIMENSION || height < 1 || height > MAX_DIMENSION) {
        throw badFile(`BLP size ${width}x${height} is outside 1..${MAX_DIMENSION}.`);
    }
    const blp = {
        compression: file[8],
        alphaDepth: file[9],
        alphaType: file[10],
        hasMips: file[11],
        width,
        height,
        offsets: Array.from({ length: MAX_LISTED_LEVELS }),
        sizes: Array.from({ length: MAX_LISTED_LEVELS }),
        fullLevelCount: 0,
        validLevelCount: 0,
    };
    switch (blp.compression) {
        case COMPRESSION.PALETTIZED:
            if (file.length < HEADER_BYTES + PALETTE_BYTES) {
                throw badFile('BLP palette is cut off.');
            }
            if (blp.alphaDepth !== 0 && blp.alphaDepth !== 1 && blp.alphaDepth !== 4 && blp.alphaDepth !== 8) {
                throw badFile(`Palettized BLP alpha depth ${blp.alphaDepth} is not 0, 1, 4 or 8.`);
            }
            break;
        case COMPRESSION.DXT:
            if (blp.alphaType !== 0 && blp.alphaType !== 1 && blp.alphaType !== 7) {
                throw badFile(`DXT BLP alpha type ${blp.alphaType} is not 0 (DXT1), 1 (DXT3) or 7 (DXT5).`);
            }
            break;
        case COMPRESSION.RAW:
            break;
        default:
            throw badFile(`Unknown BLP compression ${blp.compression}.`);
    }
    for (let i = 0; i < MAX_LISTED_LEVELS; i++) {
        blp.offsets[i] = view.getUint32(20 + (4 * i), true);
        blp.sizes[i] = view.getUint32(84 + (4 * i), true);
    }
    blp.fullLevelCount = 1 + Math.floor(Math.log2(Math.max(width, height)));
    let decoded = 0;
    for (let i = 0; i < blp.fullLevelCount; i++) {
        const [w, h] = levelSize(width, height, i);
        decoded += w * h * 4;
    }
    if (decoded > MAX_DECODED_BYTES) {
        throw badFile(`BLP ${width}x${height} would decode to ${decoded} bytes, over the ${MAX_DECODED_BYTES} limit.`);
    }
    const valid = (level) => {
        const dataStart = blp.compression === COMPRESSION.PALETTIZED ? HEADER_BYTES + PALETTE_BYTES : HEADER_BYTES;
        return blp.sizes[level] === expectedLevelBytes(blp, level) && blp.offsets[level] >= dataStart && blp.offsets[level] + blp.sizes[level] <= file.length;
    };
    if (!valid(0)) {
        throw badFile('BLP level 0 is outside the file or has the wrong size for its encoding.');
    }
    let count = 1;
    if (blp.hasMips !== 0) {
        const limit = Math.min(blp.fullLevelCount, MAX_LISTED_LEVELS);
        while (count < limit && valid(count)) {
            count++;
        }
    }
    blp.validLevelCount = count;
    blp.hasAlpha = blp.alphaDepth !== 0 && (!isDxt1(blp) || blp.alphaDepth === 1);
    blp.alpha1Bit = blp.alphaDepth === 1;
    return blp;
}

const isDxt1 = (blp) => blp.compression === COMPRESSION.DXT && blp.alphaType === 0;

function alphaPlaneBytes(blp, pixels) {
    switch (blp.alphaDepth) {
        case 1:
            return Math.floor((pixels + 7) / 8);
        case 4:
            return Math.floor((pixels + 1) / 2);
        case 8:
            return pixels;
        default:
            return 0;
    }
}

function expectedLevelBytes(blp, level) {
    const [w, h] = levelSize(blp.width, blp.height, level);
    const pixels = w * h;
    switch (blp.compression) {
        case COMPRESSION.PALETTIZED:
            return pixels + alphaPlaneBytes(blp, pixels);
        case COMPRESSION.DXT:
            return dxtLevelBytes(w, h, isDxt1(blp) ? 8 : 16);
        default:
            return pixels * 4;
    }
}

/**
 * Decodes a BLP2 file.
 * @param {Uint8Array} file
 * @returns {{width:number,height:number,hasAlpha:boolean,alpha1Bit:boolean,validLevels:number,levels:{width:number,height:number,rgba:Uint8Array}[]}}
 *   `levels[0]` is the full image; the chain runs down to 1x1.
 */
export function decodeBlp(file) {
    const blp = parseBlpHeader(file);
    const levels = [];
    for (let i = 0; i < blp.validLevelCount; i++) {
        const [width, height] = levelSize(blp.width, blp.height, i);
        const data = file.subarray(blp.offsets[i], blp.offsets[i] + blp.sizes[i]);
        levels.push({ width, height, rgba: decodeLevel(blp, file, data, width, height) });
    }
    for (let i = blp.validLevelCount; i < blp.fullLevelCount; i++) {
        levels.push(boxDown(levels[i - 1]));
    }
    return { width: blp.width, height: blp.height, hasAlpha: blp.hasAlpha, alpha1Bit: blp.hasAlpha && blp.alpha1Bit, validLevels: blp.validLevelCount, levels };
}

/** The next smaller level: each texel is the alpha-weighted average of a 2x2 block (plain average when the block is fully transparent). */
export function boxDown(source) {
    const width = Math.max(1, source.width >> 1);
    const height = Math.max(1, source.height >> 1);
    const output = new Uint8Array(width * height * 4);
    const src = source.rgba;
    for (let y = 0; y < height; y++) {
        const y0 = Math.min(y * 2, source.height - 1);
        const y1 = Math.min((y * 2) + 1, source.height - 1);
        for (let x = 0; x < width; x++) {
            const x0 = Math.min(x * 2, source.width - 1);
            const x1 = Math.min((x * 2) + 1, source.width - 1);
            const p0 = ((y0 * source.width) + x0) * 4;
            const p1 = ((y0 * source.width) + x1) * 4;
            const p2 = ((y1 * source.width) + x0) * 4;
            const p3 = ((y1 * source.width) + x1) * 4;
            const a0 = src[p0 + 3];
            const a1 = src[p1 + 3];
            const a2 = src[p2 + 3];
            const a3 = src[p3 + 3];
            const alphaSum = a0 + a1 + a2 + a3;
            const at = ((y * width) + x) * 4;
            for (let c = 0; c < 3; c++) {
                output[at + c] = alphaSum === 0
                    ? (src[p0 + c] + src[p1 + c] + src[p2 + c] + src[p3 + c] + 2) >> 2
                    : Math.floor(((src[p0 + c] * a0) + (src[p1 + c] * a1) + (src[p2 + c] * a2) + (src[p3 + c] * a3) + (alphaSum >> 1)) / alphaSum);
            }
            output[at + 3] = (alphaSum + 2) >> 2;
        }
    }
    return { width, height, rgba: output };
}

function decodeLevel(blp, file, data, width, height) {
    switch (blp.compression) {
        case COMPRESSION.PALETTIZED:
            return decodePalettized(blp, file, data, width, height);
        case COMPRESSION.DXT:
            return blp.alphaType === 0
                ? decodeDxt1(data, width, height, blp.alphaDepth === 1)
                : blp.alphaType === 1
                    ? decodeDxt3(data, width, height)
                    : decodeDxt5(data, width, height);
        default:
            return decodeRaw(blp, data, width, height);
    }
}

function decodePalettized(blp, file, data, width, height) {
    const pixels = width * height;
    const output = new Uint8Array(pixels * 4);
    const palette = new Uint8Array(256 * 3);
    for (let i = 0; i < 256; i++) {
        const at = HEADER_BYTES + (4 * i);
        palette[3 * i] = file[at + 2];
        palette[(3 * i) + 1] = file[at + 1];
        palette[(3 * i) + 2] = file[at];
    }
    const plane = data.subarray(pixels);
    for (let i = 0; i < pixels; i++) {
        const index = data[i];
        const at = i * 4;
        output[at] = palette[3 * index];
        output[at + 1] = palette[(3 * index) + 1];
        output[at + 2] = palette[(3 * index) + 2];
        switch (blp.alphaDepth) {
            case 1:
                output[at + 3] = ((plane[i >> 3] >> (i & 7)) & 1) !== 0 ? 255 : 0;
                break;
            case 4:
                output[at + 3] = ((plane[i >> 1] >> ((i & 1) * 4)) & 0xF) * 17;
                break;
            case 8:
                output[at + 3] = plane[i];
                break;
            default:
                output[at + 3] = 255;
                break;
        }
    }
    return output;
}

function decodeRaw(blp, data, width, height) {
    const pixels = width * height;
    const output = new Uint8Array(pixels * 4);
    const hasAlpha = blp.alphaDepth !== 0;
    for (let i = 0; i < pixels; i++) {
        const at = i * 4;
        output[at] = data[at + 2];
        output[at + 1] = data[at + 1];
        output[at + 2] = data[at];
        output[at + 3] = hasAlpha ? data[at + 3] : 255;
    }
    return output;
}

// ---- S3TC ----------------------------------------------------------------------------------------------------------
function checkDxt(data, width, height, blockBytes) {
    const needed = dxtLevelBytes(width, height, blockBytes);
    if (data.length < needed) {
        throw badFile(`DXT data is ${data.length} bytes but a ${width}x${height} image needs ${needed}.`);
    }
    return new Uint8Array(width * height * 4);
}

const expand565 = (value) => {
    const r5 = (value >> 11) & 0x1F;
    const g6 = (value >> 5) & 0x3F;
    const b5 = value & 0x1F;
    return [(r5 << 3) | (r5 >> 2), (g6 << 2) | (g6 >> 4), (b5 << 3) | (b5 >> 2)];
};

/** The four colours [r, g, b, a] of the block whose two RGB565 words start at `at` (ColourPalette). */
function colourPalette(data, at, fourColourOnly, transparentIndex3) {
    const c0 = data[at] | (data[at + 1] << 8);
    const c1 = data[at + 2] | (data[at + 3] << 8);
    const [r0, g0, b0] = expand565(c0);
    const [r1, g1, b1] = expand565(c1);
    const colours = [[r0, g0, b0, 255], [r1, g1, b1, 255], null, null];
    if (fourColourOnly || c0 > c1) {
        colours[2] = [Math.floor(((2 * r0) + r1) / 3), Math.floor(((2 * g0) + g1) / 3), Math.floor(((2 * b0) + b1) / 3), 255];
        colours[3] = [Math.floor((r0 + (2 * r1)) / 3), Math.floor((g0 + (2 * g1)) / 3), Math.floor((b0 + (2 * b1)) / 3), 255];
    } else {
        colours[2] = [(r0 + r1) >> 1, (g0 + g1) >> 1, (b0 + b1) >> 1, 255];
        colours[3] = [0, 0, 0, transparentIndex3 ? 0 : 255];
    }
    return colours;
}

function writeColours(data, indexAt, colours, rgba, width, height, bx, by) {
    for (let row = 0; row < 4; row++) {
        const y = (by * 4) + row;
        if (y >= height) {
            break;
        }
        const bits = data[indexAt + row];
        for (let col = 0; col < 4; col++) {
            const x = (bx * 4) + col;
            if (x >= width) {
                break;
            }
            const colour = colours[(bits >> (2 * col)) & 3];
            const at = ((y * width) + x) * 4;
            rgba[at] = colour[0];
            rgba[at + 1] = colour[1];
            rgba[at + 2] = colour[2];
            rgba[at + 3] = colour[3];
        }
    }
}

function decodeDxt1(data, width, height, keepTransparency) {
    const rgba = checkDxt(data, width, height, 8);
    const blocksX = Math.ceil(width / 4);
    const blocksY = Math.ceil(height / 4);
    for (let by = 0; by < blocksY; by++) {
        for (let bx = 0; bx < blocksX; bx++) {
            const at = ((by * blocksX) + bx) * 8;
            writeColours(data, at + 4, colourPalette(data, at, false, keepTransparency), rgba, width, height, bx, by);
        }
    }
    return rgba;
}

function decodeDxt3(data, width, height) {
    const rgba = checkDxt(data, width, height, 16);
    const blocksX = Math.ceil(width / 4);
    const blocksY = Math.ceil(height / 4);
    for (let by = 0; by < blocksY; by++) {
        for (let bx = 0; bx < blocksX; bx++) {
            const at = ((by * blocksX) + bx) * 16;
            writeColours(data, at + 12, colourPalette(data, at + 8, true, false), rgba, width, height, bx, by);
            for (let p = 0; p < 16; p++) {
                const x = (bx * 4) + (p & 3);
                const y = (by * 4) + (p >> 2);
                if (x < width && y < height) {
                    rgba[(((y * width) + x) * 4) + 3] = ((data[at + (p >> 1)] >> ((p & 1) * 4)) & 0xF) * 17;
                }
            }
        }
    }
    return rgba;
}

function decodeDxt5(data, width, height) {
    const rgba = checkDxt(data, width, height, 16);
    const blocksX = Math.ceil(width / 4);
    const blocksY = Math.ceil(height / 4);
    const alphas = new Uint8Array(8);
    for (let by = 0; by < blocksY; by++) {
        for (let bx = 0; bx < blocksX; bx++) {
            const at = ((by * blocksX) + bx) * 16;
            writeColours(data, at + 12, colourPalette(data, at + 8, true, false), rgba, width, height, bx, by);
            const a0 = data[at];
            const a1 = data[at + 1];
            alphas[0] = a0;
            alphas[1] = a1;
            if (a0 > a1) {
                for (let k = 1; k <= 6; k++) {
                    alphas[1 + k] = Math.floor((((7 - k) * a0) + (k * a1)) / 7);
                }
            } else {
                for (let k = 1; k <= 4; k++) {
                    alphas[1 + k] = Math.floor((((5 - k) * a0) + (k * a1)) / 5);
                }
                alphas[6] = 0;
                alphas[7] = 255;
            }
            // 48 bits of 3-bit indices, little-endian; split in two 24-bit halves so every shift stays inside 32 bits.
            const low = data[at + 2] | (data[at + 3] << 8) | (data[at + 4] << 16);
            const high = data[at + 5] | (data[at + 6] << 8) | (data[at + 7] << 16);
            for (let p = 0; p < 16; p++) {
                const x = (bx * 4) + (p & 3);
                const y = (by * 4) + (p >> 2);
                if (x < width && y < height) {
                    const index = p < 8 ? (low >> (3 * p)) & 7 : (high >> (3 * (p - 8))) & 7;
                    rgba[(((y * width) + x) * 4) + 3] = alphas[index];
                }
            }
        }
    }
    return rgba;
}
